"  useEffect(() => {
    // Force login screen every time the app reopens by removing saved token on startup
    const sessionKeys = [
      'pos_token',
      'pos_profile',
      'pos_current_shift',
      'pos_expenses',
      'pos_recent_orders',
      'pos_dinein_cart',
      'pos_pickup_cart',
      'pos_quick_cart',
      'pos_preorder_cart',
      'pos_table_carts',
      'pos_table_statuses',
      'pos_table_bills',
      'pos_table_bill_numbers',
      'pos_table_active_timestamps',
      'pos_kot_history',
      'pos_table_waiters',
      'pos_table_discounts',
      'pos_table_additional_charges',
      'pos_table_customers'
    ];
    sessionKeys.forEach(k => localStorage.removeItem(k));

    setIsAuthenticated(false);
    setUsername('');
    setPassword('');

    // Timer for initial loading splash screen
    const timer = setTimeout(() => {
      setShowInitialSplash(false);
    }, 2200);
    return () => clearTimeout(timer);
  }, []);"

